/** Version qualification binds executable sources and generated bytes, not Skill prose. */
import { createHash } from 'node:crypto';
import { readFileSync, readdirSync, lstatSync } from './validation-phase.mjs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');
const digest = bytes => `sha256:${createHash('sha256').update(bytes).digest('hex')}`;
const fail = message => { throw new TypeError(`platform-provenance: ${message}`); };
function fileMap(root, refs) {
  const files = {};
  const visit = ref => {
    const full = path.join(root, ref), info = lstatSync(full);
    if (info.isSymbolicLink()) fail(`source symlink: ${ref}`);
    if (info.isDirectory()) for (const name of readdirSync(full).sort()) visit(`${ref}/${name}`);
    else files[ref] = { digest: digest(readFileSync(full)), executable: Boolean(info.mode & 0o111) };
  };
  refs.forEach(visit);
  return Object.fromEntries(Object.entries(files).sort(([a], [b]) => a.localeCompare(b)));
}
export function platformSourceFingerprint(family, root = ROOT) {
  const skill = family === 'domain-driven' ? 'yss-ddd-scaffold-generator' : family === 'layered-mvc' ? 'yss-layered-mvc-scaffold-generator' : null;
  if (!skill) fail('unknown architecture');
  const base = `.agents/skills/${skill}`;
  const generator = fileMap(root, [`${base}/scripts/generate_scaffold.mjs`, ...(family === 'domain-driven' ? [`${base}/assets`] : [`${base}/assets`, '.agents/skills/yss-ddd-scaffold-generator/assets/wrapper']), 'scripts/lib/backend-platform.mjs', 'scripts/lib/scaffold-local-database.mjs']);
  const verifier = fileMap(root, ['scripts/lib/backend-platform-provenance.mjs', 'scripts/lib/backend-platform-verification.mjs', 'scripts/lib/command-runner.mjs', 'scripts/vendor/xml.mjs', '.agents/skills/yss-ddd-scaffold-generator/scripts/run_scaffold_verification.mjs']);
  return { schema_version: 1, generator_digest: digest(JSON.stringify(generator)), verifier_digest: digest(JSON.stringify(verifier)) };
}
export function assertSourceFingerprint(value, family, root = ROOT) {
  if (JSON.stringify(value) !== JSON.stringify(platformSourceFingerprint(family, root))) fail('generator/verifier source drift; requalify candidate');
}
export function generatedTreeDigest(projectRoot, manifest) {
  const expected = manifest.ownership?.generated_files;
  if (!Array.isArray(expected) || !expected.length) fail('missing generated file inventory');
  const names = new Set();
  const actual = {};
  for (const file of expected) {
    if (!file.path || path.isAbsolute(file.path) || file.path.split(/[\\/]/).some(p => p === '..' || p === '') || names.has(file.path)) fail('invalid generated file inventory');
    names.add(file.path);
    const full = path.join(projectRoot, file.path);
    // Check every path component: file lstat alone does not detect a linked parent directory.
    let current = projectRoot;
    for (const part of file.path.split('/')) { current = path.join(current, part); if (lstatSync(current).isSymbolicLink()) fail(`generated symlink: ${file.path}`); }
    const info = lstatSync(full);
    if (!info.isFile()) fail(`generated file absent: ${file.path}`);
    const hash = digest(readFileSync(full));
    if (hash.replace('sha256:', '') !== file.sha256.replace('sha256:', '')) fail(`generated file drift: ${file.path}`);
    actual[file.path] = { digest: hash, executable: Boolean(info.mode & 0o111) };
  }
  const visit = (directory, relative = '') => {
    for (const item of readdirSync(directory, { withFileTypes: true })) {
      const ref = relative ? `${relative}/${item.name}` : item.name;
      if (item.isSymbolicLink()) fail(`unexpected symlink: ${ref}`);
      if (item.isDirectory()) { if (!['target', '.git'].includes(item.name)) visit(path.join(directory, item.name), ref); }
      else if (!names.has(ref) && ref !== '.yss/scaffold-generation.json' && ref !== '.yss/platform-dependencies.json' && !ref.endsWith('/.yss/platform-dependencies.json')) fail(`unexpected source file: ${ref}`);
    }
  };
  visit(projectRoot);
  return digest(JSON.stringify(Object.fromEntries(Object.entries(actual).sort(([a],[b]) => a.localeCompare(b)))));
}

export function assertResumableCandidate(projectRoot, contract, contractBytes) {
  const manifest = JSON.parse(readFileSync(path.join(projectRoot, '.yss/scaffold-generation.json'), 'utf8'));
  if (manifest.platform_verification !== 'candidate' || manifest.schema_version !== 4 || manifest.contract_id !== contract.contract_id || manifest.contract_version !== contract.contract_version || manifest.contract_digest.replace('sha256:', '') !== digest(contractBytes).replace('sha256:', '') || JSON.stringify(manifest.platform_configuration) !== JSON.stringify(contract.platform_configuration)) fail('resume requires the identical candidate contract/Manifest');
  assertSourceFingerprint(manifest.source_fingerprint, contract.architecture_family);
  if (generatedTreeDigest(projectRoot, manifest) !== manifest.generated_tree_digest) fail('resume generated tree drift');
  return manifest;
}
